PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE Administrateur (
        Code_administrateur INTEGER PRIMARY KEY AUTOINCREMENT,
        ID_utilisateur INTEGER,
        FOREIGN KEY(ID_utilisateur) REFERENCES Utilisateur(ID_utilisateur) ON DELETE CASCADE);
CREATE TABLE Avis (
        ID_avis INTEGER PRIMARY KEY AUTOINCREMENT,
        Code_client INTEGER,
        ID_historique INTEGER,
        Note INTEGER,
        Commentaire TEXT,
        Date TEXT,
        Sentiment_score FLOAT, Sentiment_label TEXT, Keywords TEXT, Category TEXT DEFAULT 'Général', ID_parcours INTEGER,
        FOREIGN KEY(Code_client) REFERENCES Client(Code_client),
        FOREIGN KEY(ID_historique) REFERENCES Historique(ID_historique));
CREATE TABLE Bus (
        Code_bus INTEGER PRIMARY KEY AUTOINCREMENT,
        Numero_bus TEXT UNIQUE,
        Etat TEXT,
        Code_chauffeur INTEGER,
        FOREIGN KEY (Code_chauffeur) REFERENCES Chauffeur(Code_chauffeur) ON DELETE SET NULL);
CREATE TABLE Chauffeur (
        Code_chauffeur INTEGER PRIMARY KEY AUTOINCREMENT,
        ID_utilisateur INTEGER,
        Performance_score FLOAT DEFAULT 5.0,
        FOREIGN KEY(ID_utilisateur) REFERENCES Utilisateur(ID_utilisateur) ON DELETE CASCADE);
CREATE TABLE Client (
        Code_client INTEGER PRIMARY KEY AUTOINCREMENT,
        ID_utilisateur INTEGER,
        FOREIGN KEY(ID_utilisateur) REFERENCES Utilisateur(ID_utilisateur) ON DELETE CASCADE);
CREATE TABLE EmailAnalysis (
        ID_email          INTEGER PRIMARY KEY AUTOINCREMENT,
        Objet             TEXT,
        Corps             TEXT,
        Expediteur        TEXT,
        Langue            TEXT,
        Texte_traduit     TEXT,
        Categorie         TEXT,
        Sentiment         TEXT,
        Sentiment_score   REAL,
        Mots_cles         TEXT,
        Entites_extraites TEXT,
        Action_effectuee  TEXT,
        ID_action         INTEGER,
        Resume            TEXT,
        Date_analyse      TEXT);
CREATE TABLE Historique (
        ID_historique INTEGER PRIMARY KEY AUTOINCREMENT,
        Date TEXT,
        Performance_IA FLOAT,
        ID_parcours INTEGER,
        Code_chauffeur INTEGER, Heure_fin TEXT, Statut TEXT, Depart TEXT, Arrivee TEXT,
        FOREIGN KEY(ID_parcours) REFERENCES Parcours(ID_parcours),
        FOREIGN KEY(Code_chauffeur) REFERENCES Chauffeur(Code_chauffeur));
CREATE TABLE Incident (
        ID_incident INTEGER PRIMARY KEY AUTOINCREMENT,
        Description TEXT,
        Date TEXT,
        Code_chauffeur INTEGER,
        Code_Ligne INTEGER, Performance_IA FLOAT, Statut TEXT DEFAULT 'Signalé', Code_bus INTEGER,
        FOREIGN KEY(Code_chauffeur) REFERENCES Chauffeur(Code_chauffeur),
        FOREIGN KEY(Code_Ligne) REFERENCES Ligne(Code_Ligne));
CREATE TABLE Ligne (
        Code_Ligne INTEGER PRIMARY KEY AUTOINCREMENT,
        Libelle TEXT,
        Description TEXT,
        Code_bus INTEGER,
        FOREIGN KEY(Code_bus) REFERENCES Bus(Code_bus));
CREATE TABLE Parcours (
            ID_parcours INTEGER PRIMARY KEY AUTOINCREMENT,
            Depart TEXT,
            Arrivee TEXT,
            Heure_depart TEXT,
            Heure_arrivee TEXT,
            Code_Ligne INTEGER,
            FOREIGN KEY (Code_Ligne) REFERENCES Ligne (Code_Ligne)
        );
CREATE TABLE ResetCode (
        ID INTEGER PRIMARY KEY AUTOINCREMENT,
        Email TEXT,
        Code TEXT,
        Expiration DATETIME);
CREATE TABLE Utilisateur (
        ID_utilisateur INTEGER PRIMARY KEY AUTOINCREMENT,
        Nom TEXT,
        Email TEXT UNIQUE,
        Mot_de_passe TEXT,
        Role TEXT, Photo TEXT);
DELETE FROM "sqlite_sequence";
COMMIT;
